// src/lib/feeCalculator.ts
var DEFAULT_INPUTS = {
  jurisdictionSlug: "",
  shootDays: 1,
  hoursPerDay: 12,
  crewSize: 20,
  isMotion: true,
  isStudent: false,
  isNonProfit: false,
  selectedActivities: [],
  isWeekend: false,
  isParksLocation: false,
  isBeachLocation: false,
  isBuildingLocation: false,
  isPortLocation: false,
  isDWPLocation: false,
  isFloodControlLocation: false,
  numberOfLocations: 1,
  numberOfParkingSpaces: 0,
  cateringCrewSize: 0,
  numberOfCars: 0,
  prepDays: 0,
  strikeDays: 0
};
function getJurisdiction(slug) {
  const jurisdictions = jurisdictions_default.jurisdictions;
  return Object.values(jurisdictions).find((j) => j.slug === slug) || null;
}
function getReqMeta(sourceFee) {
  return {
    requirementLevel: sourceFee?.requirement_level ?? "mandatory",
    requirementNote: sourceFee?.requirement_note ?? null
  };
}
function calculateFees2(inputs) {
  const jurisdiction = getJurisdiction(inputs.jurisdictionSlug);
  const lineItems = [];
  const warnings = [];
  let complexTimeline = false;
  let maxLeadDays = jurisdiction?.minLeadDaysStandard || 5;
  if (!jurisdiction) {
    return {
      jurisdiction: null,
      lineItems: [],
      subtotalFilmLA: 0,
      subtotalJurisdiction: 0,
      subtotalPersonnel: 0,
      subtotalLocation: 0,
      estimatedTotal: 0,
      warnings: ["Jurisdiction not found in database"],
      whatPeopleMiss: [],
      complexTimeline: false,
      estimatedLeadDays: 5
    };
  }
  const baseFees = filmla_base_fees_default.fees;
  const lowImpact = !!inputs.lowImpactTier && inputs.jurisdictionSlug === "los-angeles" && inputs.isMotion && !inputs.isStudent && !inputs.isNonProfit;
  if (inputs.isStudent) {
    const isComplex = inputs.selectedActivities.length > 0;
    lineItems.push({
      id: "filmla_app",
      name: isComplex ? "Student Permit (Complex)" : "Student Permit (Simple)",
      amount: isComplex ? baseFees.student_permit_complex.rate : baseFees.student_permit_simple.rate,
      per: "permit",
      category: "filmla"
    });
  } else if (inputs.isNonProfit) {
    lineItems.push({
      id: "filmla_app",
      name: "Non-Profit (PSA) Permit App",
      amount: baseFees.nonprofit_psa_app.rate,
      per: "permit",
      category: "filmla"
    });
  } else if (inputs.isMotion) {
    if (lowImpact) {
      lineItems.push({
        id: "filmla_app",
        name: "Low Impact Permit Application",
        amount: FEE_MATH.lowImpact.application,
        per: "permit",
        category: "filmla",
        note: "FilmLA Low Impact pilot \u2014 likely rate, pending FilmLA confirmation"
      });
    } else {
      lineItems.push({
        id: "filmla_app",
        name: "Permit Application Fee",
        amount: baseFees.permit_application.rate,
        per: "permit",
        category: "filmla",
        note: "Up to 5 locations, 7 consecutive days"
      });
    }
    if (inputs.shootDays > 7) {
      const extraRiders = Math.ceil((inputs.shootDays - 7) / 7);
      lineItems.push({
        id: "filmla_riders",
        name: `Permit Rider(s) \xC3\x97 ${extraRiders}`,
        amount: baseFees.permit_rider_business_hours.rate * extraRiders,
        per: "rider",
        category: "filmla",
        note: "Additional 7-day blocks"
      });
    }
    if (inputs.numberOfLocations > 5) {
      warnings.push(`Your ${inputs.numberOfLocations} locations exceed the base 5 included in the permit \xE2\x80\x94 additional rider fees may apply.`);
    }
  } else {
    if (inputs.crewSize >= 16) {
      lineItems.push({
        id: "filmla_app",
        name: "Still Photo App (Motion Rate \xE2\x80\x94 16+ crew)",
        amount: baseFees.permit_application.rate,
        per: "permit",
        category: "filmla",
        note: "Crew of 16+ requires Motion application fee"
      });
      warnings.push("Still photo crew of 16+ triggers Motion application rate ($931 instead of $104).");
    } else {
      lineItems.push({
        id: "filmla_app",
        name: "Still Photo Application Fee",
        amount: baseFees.still_photo_application.rate,
        per: "permit",
        category: "filmla"
      });
    }
  }
  if (lowImpact) {
    lineItems.push({
      id: "filmla_notification",
      name: "Notification Fee (Low Impact)",
      amount: FEE_MATH.lowImpact.notificationPerLocation * inputs.numberOfLocations,
      per: `${inputs.numberOfLocations} filming location${inputs.numberOfLocations === 1 ? "" : "s"}`,
      category: "filmla",
      note: "Cast/crew parking & base camp locations are free"
    });
  } else {
    lineItems.push({
      id: "filmla_notification",
      name: "Notification Fee",
      amount: baseFees.notification_fee.rate * inputs.numberOfLocations,
      per: `notification radius (est. 1 per location \xD7 ${inputs.numberOfLocations})`,
      category: "filmla",
      note: "Billed per notification radius \u2014 typically one per filming location; locations sharing a radius may lower this.",
      isEstimate: inputs.numberOfLocations > 1
    });
  }
  for (const activityId of inputs.selectedActivities) {
    switch (activityId) {
      case "street_closure":
        lineItems.push({
          id: "filmla_lane_admin",
          name: "Lane Closure Administration",
          amount: baseFees.lane_closure_admin.rate * inputs.numberOfLocations,
          per: "involved location",
          category: "filmla"
        });
        complexTimeline = true;
        maxLeadDays = Math.max(maxLeadDays, jurisdiction.minLeadDaysComplex || 10);
        break;
      case "gunfire_sfx":
        lineItems.push({
          id: "filmla_gunfire_admin",
          name: "Gunfire Administration",
          amount: baseFees.gunfire_admin.rate * inputs.numberOfLocations,
          per: "involved location",
          category: "filmla"
        });
        complexTimeline = true;
        maxLeadDays = Math.max(maxLeadDays, jurisdiction.minLeadDaysComplex || 10);
        break;
      case "pyrotechnics":
        lineItems.push({
          id: "filmla_sfx_admin",
          name: "Special FX Administration",
          amount: baseFees.special_fx_admin.rate * inputs.numberOfLocations,
          per: "involved location",
          category: "filmla"
        });
        complexTimeline = true;
        maxLeadDays = Math.max(maxLeadDays, jurisdiction.minLeadDaysComplex || 10);
        break;
      case "drone_aerial":
        lineItems.push({
          id: "filmla_drone_admin",
          name: "Drone Administration",
          amount: baseFees.drone_admin.rate * inputs.numberOfLocations,
          per: "involved location",
          category: "filmla"
        });
        complexTimeline = true;
        maxLeadDays = Math.max(maxLeadDays, jurisdiction.minLeadDaysComplex || 10);
        break;
    }
  }
  const monitorLikely = inputs.selectedActivities.length > 0 || inputs.isParksLocation || inputs.isPortLocation || inputs.isBeachLocation || inputs.isFloodControlLocation;
  const monitorHours = inputs.hoursPerDay + 1;
  if (monitorLikely) lineItems.push({
    id: "filmla_monitor",
    name: "FilmLA Monitor",
    isEstimate: true,
    amount: baseFees.filmla_monitor.rate * monitorHours * inputs.shootDays,
    per: `${monitorHours}hrs \xC3\x97 ${inputs.shootDays} days`,
    category: "filmla",
    note: "Includes 1hr early arrival. Subject to OT/DT."
  });
  const jFees = jurisdiction.fees;
  if (inputs.jurisdictionSlug === "los-angeles") {
    if (inputs.crewSize >= 16) {
      if (lowImpact) {
        lineItems.push({
          id: "la_fire_spot_check",
          name: "LAFD Spot Check \u2014 Waived",
          amount: FEE_MATH.lowImpact.lafdSpotCheck,
          per: "permit",
          category: "jurisdiction",
          department: "LA City Fire Department",
          note: "Waived under the Low Impact pilot"
        });
      } else {
        lineItems.push({
          id: "la_fire_spot_check",
          name: "LAFD Spot Check Surcharge",
          amount: jFees.fire_spot_check.rate,
          per: "permit",
          category: "jurisdiction",
          department: "LA City Fire Department",
          note: "Automatic for crews of 16+"
        });
      }
    }
    if (inputs.selectedActivities.includes("pyrotechnics") || inputs.selectedActivities.includes("gunfire_sfx")) {
      const fireHours = Math.max(jFees.fire_safety_officer.minimumHours, inputs.hoursPerDay) + jFees.fire_safety_officer.travelHours;
      lineItems.push({
        id: "la_fire_safety",
        name: "Fire Safety Officer",
        amount: jFees.fire_safety_officer.rate * fireHours * inputs.shootDays,
        per: `${fireHours}hrs \xC3\x97 ${inputs.shootDays} days`,
        category: "personnel",
        department: "LA City Fire Department",
        note: `${jFees.fire_safety_officer.minimumHours}hr min + 1hr travel`
      });
    }
    if (inputs.selectedActivities.includes("street_closure")) {
      lineItems.push({
        id: "la_lane_closure",
        name: "Lane & Street Closure Fee",
        amount: jFees.lane_street_closure.rate * inputs.numberOfLocations,
        per: "involved location",
        category: "jurisdiction",
        department: "LA City"
      });
      const lapdHours = Math.max(jFees.lapd_retired_off_duty.minimumHours || 8, inputs.hoursPerDay);
      lineItems.push({
        id: "la_lapd",
        name: "LAPD Officer (Retired/Off-Duty)",
        amount: (jFees.lapd_retired_off_duty.rateMin + jFees.lapd_retired_off_duty.rateMax) / 2 * lapdHours * inputs.shootDays,
        per: `~${lapdHours}hrs \xD7 ${inputs.shootDays} days`,
        category: "personnel",
        department: "LAPD",
        note: `8hr minimum. Paid directly to provider`,
        isEstimate: true,
        paidDirectly: true,
        rateLow: jFees.lapd_retired_off_duty.rateMin * lapdHours * inputs.shootDays,
        rateHigh: jFees.lapd_retired_off_duty.rateMax * lapdHours * inputs.shootDays
      });
    }
    if (inputs.isParksLocation) {
      lineItems.push({
        id: "la_parks_use",
        name: "Rec & Parks \xE2\x80\x94 Film Use",
        amount: jFees.rec_parks_film_use.rate * inputs.shootDays,
        per: `${inputs.shootDays} days`,
        category: "location",
        department: "LA Dept of Rec & Parks"
      });
      if (inputs.prepDays > 0) {
        lineItems.push({
          id: "la_parks_prep",
          name: "Rec & Parks \xE2\x80\x94 Prep/Strike",
          amount: jFees.rec_parks_prep_strike.rate * (inputs.prepDays + inputs.strikeDays),
          per: `${inputs.prepDays + inputs.strikeDays} days`,
          category: "location",
          department: "LA Dept of Rec & Parks"
        });
      }
      lineItems.push({
        id: "la_parks_monitor",
        name: "Rec & Parks Monitor",
        amount: jFees.rec_parks_monitor.rate * (inputs.hoursPerDay + 1) * inputs.shootDays,
        per: "hour",
        category: "personnel",
        department: "LA Dept of Rec & Parks"
      });
      lineItems.push({
        id: "la_parks_monitor_reporting",
        name: "Rec & Parks Monitor Reporting",
        amount: jFees.rec_parks_monitor_reporting.rate * inputs.shootDays,
        per: "shift",
        category: "personnel",
        department: "LA Dept of Rec & Parks"
      });
    }
    if (inputs.isPortLocation) {
      lineItems.push({
        id: "la_port_use",
        name: "Port of LA \xE2\x80\x94 Use Fee",
        amount: jFees.port_use_fee.rate * inputs.shootDays,
        per: `${inputs.shootDays} days`,
        category: "location",
        department: "Port of Los Angeles"
      });
    }
  }
  if (inputs.jurisdictionSlug === "los-angeles-county") {
    if (inputs.isMotion) {
      lineItems.push({
        id: "lac_fire_review",
        name: "County Fire \xE2\x80\x94 Filming Review",
        amount: jFees.fire_filming_review.rate,
        per: "permit",
        category: "jurisdiction",
        department: "LA County Fire"
      });
    } else if (inputs.crewSize >= 16) {
      lineItems.push({
        id: "lac_fire_review",
        name: "County Fire \xE2\x80\x94 Still Photo Review",
        amount: jFees.fire_still_photo_review.rate,
        per: "permit",
        category: "jurisdiction",
        department: "LA County Fire",
        note: "16+ People"
      });
    }
    if (inputs.selectedActivities.includes("pyrotechnics") || inputs.selectedActivities.includes("gunfire_sfx")) {
      lineItems.push({
        id: "lac_sfx_permit",
        name: "County Fire \xE2\x80\x94 Special Effects Permit",
        amount: jFees.fire_special_effects_permit.rate * inputs.numberOfLocations,
        per: "involved location",
        category: "jurisdiction",
        department: "LA County Fire"
      });
      const fsoHours = Math.max(jFees.fire_safety_officer.minimumHours, inputs.hoursPerDay);
      lineItems.push({
        id: "lac_fso",
        name: "County Fire Safety Officer",
        amount: jFees.fire_safety_officer.rate * fsoHours * inputs.shootDays,
        per: `${fsoHours}hrs \xC3\x97 ${inputs.shootDays} days`,
        category: "personnel",
        department: "LA County Fire",
        note: "4hr min, Flat Rate (No OT/DT). Paid directly to provider",
        paidDirectly: true
      });
    }
    if (inputs.selectedActivities.includes("street_closure")) {
      lineItems.push({
        id: "lac_roads_inspection",
        name: "County Roads \xE2\x80\x94 Inspection/Use",
        amount: jFees.roads_inspection_use.rate * inputs.shootDays,
        per: `${inputs.shootDays} days`,
        category: "jurisdiction",
        department: "LA County Roads"
      });
      lineItems.push({
        id: "lac_roads_encroachment",
        name: "County Roads \xE2\x80\x94 Encroachment Processing",
        amount: jFees.roads_encroachment_processing.rate,
        per: "area",
        category: "jurisdiction",
        department: "LA County Roads"
      });
      lineItems.push({
        id: "lac_roads_app",
        name: "County Roads \xE2\x80\x94 Application/Issuance",
        amount: jFees.roads_application_issuance.rate * inputs.numberOfLocations,
        per: "involved location",
        category: "jurisdiction",
        department: "LA County Roads"
      });
      const sheriffHours = Math.max(jFees.sheriff_officer.minimumHours, inputs.hoursPerDay);
      lineItems.push({
        id: "lac_sheriff",
        name: "County Sheriff Officer",
        amount: jFees.sheriff_officer.rate * sheriffHours * inputs.shootDays,
        per: `${sheriffHours}hrs \xC3\x97 ${inputs.shootDays} days`,
        category: "personnel",
        department: "LA County Sheriff",
        note: "6hr min, Flat Rate + $1.22/mile mileage. Paid directly to provider",
        paidDirectly: true,
        isEstimate: true
      });
    }
    if (inputs.isBeachLocation) {
      lineItems.push({
        id: "lac_beach_use",
        name: "County Beaches \xE2\x80\x94 Filming Use",
        amount: jFees.beaches_filming_use.rate * inputs.shootDays,
        per: `${inputs.shootDays} days`,
        category: "location",
        department: "LA County Beaches"
      });
      if (inputs.prepDays > 0 || inputs.strikeDays > 0) {
        const totalPrepStrike = inputs.prepDays + inputs.strikeDays;
        const basicDays = Math.min(totalPrepStrike, 3);
        const extendedDays = Math.max(0, totalPrepStrike - 3);
        let prepCost = basicDays * jFees.beaches_prep_strike.rate;
        if (extendedDays > 0) {
          prepCost += extendedDays * jFees.beaches_prep_strike_extended.rate;
        }
        lineItems.push({
          id: "lac_beach_prep",
          name: "County Beaches \xE2\x80\x94 Prep/Strike",
          amount: prepCost,
          per: `${totalPrepStrike} days`,
          category: "location",
          department: "LA County Beaches",
          note: extendedDays > 0 ? `$100/day first 3 days, $400/day after` : void 0
        });
      }
    }
    if (inputs.isParksLocation) {
      lineItems.push({
        id: "lac_parks_use",
        name: "County Parks \xE2\x80\x94 Filming Use",
        amount: jFees.parks_filming_use.rate * inputs.shootDays,
        per: `${inputs.shootDays} days`,
        category: "location",
        department: "LA County Parks"
      });
    }
    if (inputs.isFloodControlLocation) {
      lineItems.push({
        id: "lac_flood_permit",
        name: "Flood Control \xE2\x80\x94 Permit Issuance",
        amount: jFees.flood_control_permit.rate,
        per: "permit",
        category: "jurisdiction",
        department: "LA County Flood Control"
      });
      const totalFloodDays = inputs.shootDays + inputs.prepDays + inputs.strikeDays;
      lineItems.push({
        id: "lac_flood_use",
        name: "Flood Control \xE2\x80\x94 Use Fee",
        amount: jFees.flood_control_use.rate * totalFloodDays,
        per: `${totalFloodDays} days (all activity days)`,
        category: "location",
        department: "LA County Flood Control",
        note: "Applies to ALL prep, strike, still photo & filming days"
      });
      warnings.push(`Flood control locations are $${jFees.flood_control_use.rate.toLocaleString()}/day \xE2\x80\x94 one of the highest daily rates in LA County.`);
    }
  }
  if (inputs.jurisdictionSlug === "culver-city") {
    lineItems.push({
      id: "cc_application",
      name: "Culver City Application Fee",
      amount: jFees.city_application.rate,
      per: "permit",
      category: "jurisdiction",
      department: "Culver City",
      note: "In addition to FilmLA application fee"
    });
    if (inputs.isMotion) {
      lineItems.push({
        id: "cc_daily_use",
        name: "Culver City Filming Daily Use",
        amount: jFees.filming_daily_use.rate * inputs.shootDays,
        per: `${inputs.shootDays} days`,
        category: "jurisdiction",
        department: "Culver City"
      });
    } else {
      lineItems.push({
        id: "cc_daily_use",
        name: "Culver City Still Photo Daily Use",
        amount: jFees.still_photo_daily_use.rate * inputs.shootDays,
        per: `${inputs.shootDays} days`,
        category: "jurisdiction",
        department: "Culver City"
      });
    }
    lineItems.push({
      id: "cc_fire_spot",
      name: "Culver City Fire Spot Check",
      amount: jFees.fire_spot_check.rate * inputs.numberOfLocations,
      per: "involved location",
      category: "jurisdiction",
      department: "Culver City Fire Department"
    });
    if (inputs.selectedActivities.includes("street_closure")) {
      if (inputs.isWeekend) {
        lineItems.push({
          id: "cc_police",
          name: "Culver City Police Officer (Weekend/Holiday)",
          amount: jFees.police_officer_weekend_holiday.rate * inputs.shootDays,
          per: `${inputs.shootDays} days`,
          category: "personnel",
          department: "Culver City Police"
        });
      } else {
        const basePolice = jFees.police_officer_weekday.rate;
        const extraHours = Math.max(0, inputs.hoursPerDay - 8);
        const extraCost = extraHours * jFees.police_officer_additional_hours.rate;
        lineItems.push({
          id: "cc_police",
          name: "Culver City Police Officer (Weekday)",
          amount: (basePolice + extraCost) * inputs.shootDays,
          per: `${inputs.shootDays} days`,
          category: "personnel",
          department: "Culver City Police",
          note: "8hr minimum included"
        });
      }
    }
    if (inputs.selectedActivities.includes("pyrotechnics") || inputs.selectedActivities.includes("gunfire_sfx")) {
      if (inputs.isWeekend) {
        lineItems.push({
          id: "cc_fire_officer",
          name: "Culver City Fire Officer (Weekend/Holiday)",
          amount: jFees.fire_officer_weekend_holiday.rate * inputs.shootDays,
          per: `${inputs.shootDays} days`,
          category: "personnel",
          department: "Culver City Fire"
        });
      } else {
        const baseFire = jFees.fire_officer_weekday.rate;
        const extraFireHours = Math.max(0, inputs.hoursPerDay - 8);
        const extraFireCost = extraFireHours * jFees.fire_officer_additional_hours.rate;
        lineItems.push({
          id: "cc_fire_officer",
          name: "Culver City Fire Officer (Weekday)",
          amount: (baseFire + extraFireCost) * inputs.shootDays,
          per: `${inputs.shootDays} days`,
          category: "personnel",
          department: "Culver City Fire",
          note: "8hr minimum included"
        });
      }
    }
    if (inputs.numberOfParkingSpaces > 0) {
      lineItems.push({
        id: "cc_posting",
        name: "Parking Posting (Non-Metered)",
        amount: jFees.posting_non_metered.rate * inputs.numberOfParkingSpaces * inputs.shootDays,
        per: `${inputs.numberOfParkingSpaces} spaces \xC3\x97 ${inputs.shootDays} days`,
        category: "jurisdiction",
        department: "Culver City",
        note: "Using non-metered rate \xE2\x80\x94 downtown/metered rates higher"
      });
    }
  }
  const filmlaReqMap = {
    filmla_app: inputs.isStudent ? inputs.selectedActivities.length > 0 ? baseFees.student_permit_complex : baseFees.student_permit_simple : inputs.isNonProfit ? baseFees.nonprofit_psa_app : inputs.isMotion ? baseFees.permit_application : inputs.crewSize >= 16 ? baseFees.permit_application : baseFees.still_photo_application,
    filmla_riders: baseFees.permit_rider_business_hours,
    filmla_notification: baseFees.notification_fee,
    filmla_lane_admin: baseFees.lane_closure_admin,
    filmla_gunfire_admin: baseFees.gunfire_admin,
    filmla_sfx_admin: baseFees.special_fx_admin,
    filmla_drone_admin: baseFees.drone_admin,
    filmla_monitor: baseFees.filmla_monitor
  };
  const jReqMap = jFees ? {
    la_fire_spot_check: jFees.fire_spot_check,
    la_fire_safety: jFees.fire_safety_officer,
    la_lane_closure: jFees.lane_street_closure,
    la_lapd: jFees.lapd_retired_off_duty,
    la_parks_use: jFees.rec_parks_film_use,
    la_parks_prep: jFees.rec_parks_prep_strike,
    la_parks_monitor: jFees.rec_parks_monitor,
    la_parks_monitor_reporting: jFees.rec_parks_monitor_reporting,
    la_port_use: jFees.port_use_fee,
    lac_fire_review: jFees.fire_filming_review || jFees.fire_still_photo_review,
    lac_sfx_permit: jFees.fire_special_effects_permit,
    lac_fso: jFees.fire_safety_officer,
    lac_roads_inspection: jFees.roads_inspection_use,
    lac_roads_encroachment: jFees.roads_encroachment_processing,
    lac_roads_app: jFees.roads_application_issuance,
    lac_sheriff: jFees.sheriff_officer,
    lac_beach_use: jFees.beaches_filming_use,
    lac_beach_prep: jFees.beaches_prep_strike,
    lac_parks_use: jFees.parks_filming_use,
    lac_flood_permit: jFees.flood_control_permit,
    lac_flood_use: jFees.flood_control_use,
    cc_application: jFees.city_application,
    cc_daily_use: jFees.filming_daily_use || jFees.still_photo_daily_use,
    cc_fire_spot: jFees.fire_spot_check,
    cc_police: jFees.police_officer_weekday || jFees.police_officer_weekend_holiday,
    cc_fire_officer: jFees.fire_officer_weekday || jFees.fire_officer_weekend_holiday,
    cc_posting: jFees.posting_non_metered
  } : {};
  const allReqMap = { ...filmlaReqMap, ...jReqMap };
  for (const item of lineItems) {
    const src = allReqMap[item.id];
    if (src && !item.requirementLevel) {
      const meta = getReqMeta(src);
      item.requirementLevel = meta.requirementLevel;
      item.requirementNote = meta.requirementNote;
    }
    if (!item.requirementLevel) {
      item.requirementLevel = "mandatory";
    }
  }
  const subtotalFilmLA = lineItems.filter((i) => i.category === "filmla").reduce((sum, i) => sum + i.amount, 0);
  const subtotalJurisdiction = lineItems.filter((i) => i.category === "jurisdiction").reduce((sum, i) => sum + i.amount, 0);
  const subtotalPersonnel = lineItems.filter((i) => i.category === "personnel").reduce((sum, i) => sum + i.amount, 0);
  const subtotalLocation = lineItems.filter((i) => i.category === "location").reduce((sum, i) => sum + i.amount, 0);
  const estimatedTotal = subtotalFilmLA + subtotalJurisdiction + subtotalPersonnel + subtotalLocation;
  for (const actId of inputs.selectedActivities) {
    const activity = activities_default.activities.find((a) => a.id === actId);
    if (activity) {
      if (activity.triggersComplexTimeline) complexTimeline = true;
      maxLeadDays = Math.max(maxLeadDays, (jurisdiction.minLeadDaysStandard || 5) + (activity.additionalLeadDays || 0));
    }
  }
  return {
    jurisdiction,
    lineItems,
    subtotalFilmLA,
    subtotalJurisdiction,
    subtotalPersonnel,
    subtotalLocation,
    estimatedTotal,
    warnings,
    whatPeopleMiss: jurisdiction.whatPeopleMiss || [],
    complexTimeline,
    estimatedLeadDays: maxLeadDays
  };
}

// src/lib/mcp/tools/calculate-permit-fees.ts
var calculate_permit_fees_default = defineTool2({
  name: "calculate_permit_fees",
  title: "Calculate film permit fees",
  description: "Estimate itemized film permit fees for a planned shoot in a supported jurisdiction (e.g. City of Los Angeles, LA County). Combines FilmLA base fees with jurisdiction-specific personnel and location surcharges. Returns line items, subtotals, an estimated total, warnings, and estimated lead time. Optionally applies FilmLA Low Impact pilot pricing (LA City motion only). Estimate only \u2014 not a quote.",
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  inputSchema: {
    jurisdictionSlug: z2.string().describe("Jurisdiction slug, e.g. 'los-angeles', 'los-angeles-county'."),
    shootDays: z2.number().int().min(1).describe("Number of shoot days."),
    hoursPerDay: z2.number().min(1).max(24).describe("Hours per shoot day."),
    crewSize: z2.number().int().min(1).describe("Crew size."),
    isMotion: z2.boolean().describe("True for motion filming, false for still photo."),
    isStudent: z2.boolean().optional(),
    isNonProfit: z2.boolean().optional(),
    selectedActivities: z2.array(z2.string()).optional().describe("Activity IDs, e.g. street_closure, gunfire_sfx, pyrotechnics, drone_aerial."),
    isWeekend: z2.boolean().optional(),
    isParksLocation: z2.boolean().optional(),
    isBeachLocation: z2.boolean().optional(),
    isBuildingLocation: z2.boolean().optional(),
    isPortLocation: z2.boolean().optional(),
    isDWPLocation: z2.boolean().optional(),
    isFloodControlLocation: z2.boolean().optional(),
    numberOfLocations: z2.number().int().min(1).optional(),
    numberOfParkingSpaces: z2.number().int().min(0).optional(),
    cateringCrewSize: z2.number().int().min(0).optional(),
    numberOfCars: z2.number().int().min(0).optional(),
    prepDays: z2.number().int().min(0).optional(),
    strikeDays: z2.number().int().min(0).optional(),
    lowImpactTier: z2.boolean().optional().describe(
      "Apply FilmLA Low Impact pilot pricing. Only affects LA City motion, non-student, non-profit shoots; ignored otherwise. Confirm eligibility with evaluate_low_impact_precheck first."
    )
  },
  handler: (input) => {
    const inputs = {
      ...DEFAULT_INPUTS,
      ...input,
      isStudent: !!input.isStudent,
      isNonProfit: !!input.isNonProfit,
      selectedActivities: input.selectedActivities ?? [],
      isWeekend: !!input.isWeekend,
      isParksLocation: !!input.isParksLocation,
      isBeachLocation: !!input.isBeachLocation,
      isBuildingLocation: !!input.isBuildingLocation,
      isPortLocation: !!input.isPortLocation,
      isDWPLocation: !!input.isDWPLocation,
      isFloodControlLocation: !!input.isFloodControlLocation,
      numberOfLocations: input.numberOfLocations ?? 1,
      numberOfParkingSpaces: input.numberOfParkingSpaces ?? 0,
      cateringCrewSize: input.cateringCrewSize ?? 0,
      numberOfCars: input.numberOfCars ?? 0,
      prepDays: input.prepDays ?? 0,
      strikeDays: input.strikeDays ?? 0
    };
    const result = calculateFees2(inputs);
    const lines = result.lineItems.map(
      (li) => `- ${li.name}: $${Math.round(li.amount)}${li.isEstimate ? " (est.)" : ""}${li.note ? ` \u2014 ${li.note}` : ""}`
    );
    const text = [
      `Jurisdiction: ${result.jurisdiction?.name ?? inputs.jurisdictionSlug}`,
      `Estimated total: $${Math.round(result.estimatedTotal)}`,
      `Estimated lead time: ${result.estimatedLeadDays} days${result.complexTimeline ? " (complex)" : ""}`,
      "",
      "Line items:",
      ...lines,
      result.warnings.length ? `
Warnings:
${result.warnings.map((w) => `- ${w}`).join("\n")}` : "",
      "\nEstimate only \u2014 not a quote. Cross-check with FilmLA before submitting."
    ].filter(Boolean).join("\n");
    return {
      content: [{ type: "text", text }],
      structuredContent: { result }
    };
  }
});

